import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, ActivatedRoute, Router } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../core/services/api.service';

@Component({
  selector: 'app-destination-form',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h2>{{ isEdit ? 'Sửa' : 'Tạo' }} điểm đến</h2></div></div>
    <section class="section">
      <div class="container container-sm">
        <div class="card">
          <div class="card-body">
            <form (ngSubmit)="save()">
              <div class="form-group"><label>Tên *</label><input type="text" class="form-control" [(ngModel)]="form.name" name="name" required></div>
              <div class="form-group"><label>Slug *</label><input type="text" class="form-control" [(ngModel)]="form.slug" name="slug" required></div>
              <div class="grid grid-2">
                <div class="form-group"><label>Tỉnh/Thành *</label><select class="form-control" [(ngModel)]="form.provinceId" name="provinceId" required><option value="">Chọn tỉnh/thành</option><option *ngFor="let p of provinces" [value]="p.id">{{ p.name }}</option></select></div>
                <div class="form-group"><label>Danh mục *</label><select class="form-control" [(ngModel)]="form.categoryId" name="categoryId" required><option value="">Chọn danh mục</option><option *ngFor="let c of categories" [value]="c.id">{{ c.name }}</option></select></div>
              </div>
              <div class="form-group"><label>Địa chỉ *</label><input type="text" class="form-control" [(ngModel)]="form.address" name="address" required></div>
              <div class="form-group"><label>Mô tả ngắn</label><input type="text" class="form-control" [(ngModel)]="form.shortDescription" name="shortDescription"></div>
              <div class="form-group"><label>Mô tả chi tiết *</label><textarea class="form-control" [(ngModel)]="form.description" name="description" rows="5" required></textarea></div>
              <div class="grid grid-2">
                <div class="form-group"><label>Thời gian đẹp nhất</label><input type="text" class="form-control" [(ngModel)]="form.bestTime" name="bestTime" placeholder="VD: Tháng 3-5"></div>
                <div class="form-group"><label>Chi phí ước tính</label><input type="text" class="form-control" [(ngModel)]="form.estimatedCost" name="estimatedCost" placeholder="VD: 500.000 - 1.000.000đ"></div>
              </div>
              <div class="form-group"><label>URL hình ảnh chính</label><input type="text" class="form-control" [(ngModel)]="primaryImageUrl" name="imageUrl" placeholder="https://..."></div>
              <div class="form-group"><label>Mẹo du lịch</label><textarea class="form-control" [(ngModel)]="form.tips" name="tips" rows="3"></textarea></div>
              <div class="form-group"><label><input type="checkbox" [(ngModel)]="form.isFeatured"> Đánh dấu nổi bật</label></div>
              <div class="form-group"><label><input type="checkbox" [(ngModel)]="form.isActive"> Hoạt động</label></div>
              <div class="form-error" *ngIf="error">{{ error }}</div>
              <div style="display:flex;gap:0.75rem;">
                <button type="submit" class="btn btn-primary" [disabled]="loading">{{ loading ? 'Đang lưu...' : 'Lưu' }}</button>
                <a routerLink="/admin/destinations" class="btn btn-outline">Hủy</a>
              </div>
            </form>
          </div>
        </div>
      </div>
    </section>
  `
})
export class DestinationFormComponent implements OnInit {
  isEdit = false;
  form: any = { isFeatured: false, isActive: true };
  provinces: any[] = [];
  categories: any[] = [];
  primaryImageUrl = '';
  loading = false;
  error = '';

  constructor(private api: ApiService, private route: ActivatedRoute, private router: Router) {}

  ngOnInit() {
    this.api.getProvinces().subscribe(d => { this.provinces = d; });
    this.api.getDestinationCategories().subscribe(d => { this.categories = d; });
    const id = this.route.snapshot.paramMap.get('id');
    if (id) {
      this.isEdit = true;
      this.api.getDestination(id).subscribe(d => {
        this.form = { ...d };
        this.primaryImageUrl = d.images?.[0]?.url || '';
      });
    }
  }

  save() {
    this.loading = true;
    this.error = '';
    const data: any = { ...this.form };
    if (this.primaryImageUrl) {
      data.images = [{ url: this.primaryImageUrl, isPrimary: true, sortOrder: 0 }];
    }
    const action = this.isEdit
      ? this.api.updateDestination(this.form.id, data)
      : this.api.createDestination(data);
    action.subscribe({
      next: () => { this.router.navigate(['/admin/destinations']); },
      error: (err) => { this.error = err.error?.error || 'Lưu thất bại'; this.loading = false; }
    });
  }
}
